 for(std::size_t i=0;i<points.size();i++){const auto& p=after.eventIndex->back().geometry[i];const auto& old=originalEvent.geometry[i];assert(p.timestampUs==old.timestampUs&&p.tiltX==old.tiltX&&p.tiltY==old.tiltY&&p.deviceKind==old.deviceKind&&p.capabilities==old.capabilities);if(i<3||i>7)assert(p==old);}
 assert(after.eventIndex->back().geometry[5].x==104&&after.eventIndex->back().geometry[5].y==92&&after.eventIndex->back().geometry[5].pressure==.7);assert(doc.undo()&&doc.snapshot().sameContent(before));assert(doc.redo()&&doc.snapshot().sameContent(after));
