 assert(!localStrokeEditCommand(before,originalEvent.id,5,25,0,0,.6));assert(!localStrokeEditCommand(before,originalEvent.id,0,25,-128,0,0));assert(!localStrokeEditCommand(before,originalEvent.id,5,129,1,0,0));assert(!localStrokeEditCommand(before,originalEvent.id,5,0,1,0,0));assert(!localStrokeEditCommand(before,originalEvent.id,11,25,1,0,0));assert(!localStrokeEditCommand(before,originalEvent.id,5,25,0,0,0));std::stop_source stop;stop.request_stop();assert(!localStrokeEditCommand(before,originalEvent.id,5,25,1,0,0,stop.get_token()));
 auto locked=before;auto nodes=std::make_shared<NodeMap>(*before.nodes);locked.nodes=nodes;nodes->at(layer).locked=true;assert(!localStrokeEditCommand(locked,originalEvent.id,5,25,1,0,0));auto ld=Document::fromSnapshot(locked);assert(ld&&!ld.value().apply(command.value(),locked.revision));
 // Same physical points get identical weights despite different sampling density.
 auto dense=before;auto events=std::make_shared<EventList>(*before.eventIndex);dense.eventIndex=events;auto& g=events->back().geometry;g.clear();for(unsigned i=0;i<21;i++)g.push_back({50+5.*i,100,.5,2.,3.,originalEvent.startUs+i*5,1,3});auto denseCommand=localStrokeEditCommand(dense,originalEvent.id,10,25,4,-8,.2);assert(denseCommand);const auto& dg=std::get<AdjustStrokeSamples>(denseCommand.value().operations.front()).geometry;const auto& sparse=std::get<AdjustStrokeSamples>(command.value().operations.front()).geometry;for(unsigned i=0;i<11;i++){assert(dg[2*i].x==sparse[i].x&&dg[2*i].y==sparse[i].y&&dg[2*i].pressure==sparse[i].pressure);}
 auto coincident=before;events=std::make_shared<EventList>(*before.eventIndex);coincident.eventIndex=events;for(auto& p:events->back().geometry){p.x=100;p.y=100;}auto coincidentEdit=localStrokeEditCommand(coincident,originalEvent.id,5,1,1,2,.1);assert(coincidentEdit);for(const auto& p:std::get<AdjustStrokeSamples>(coincidentEdit.value().operations.front()).geometry)assert(p.x==101&&p.y==102&&p.pressure==.6);
 // Older selected smooth stroke remains editable across only independent
