 auto older=before;auto later=std::make_shared<EventList>(*before.eventIndex);older.eventIndex=later;
 for(auto engine:{1u,2u,10u,12u,19u}){auto e=originalEvent;e.id=Id::fromNumber(100+engine);e.engineVersion=engine;e.toolId=engine==10?"fineliner-aa":engine==12?"dry-ink":engine==19?"smooth-ink-aa":engine==2?"eraser":"pencil";if(engine==1)e.style=StrokeStyle{};else if(engine==10)e.style.width=4;const auto delta=1000*engine;e.startUs+=delta;e.endUs+=delta;for(auto& p:e.geometry)p.timestampUs+=delta;later->push_back(e);assert(independentNativeStroke(older,e));}
 auto eligible=editableStrokeIndex(older,originalEvent.id);assert(eligible&&eligible.value()==1);auto oldEdit=localStrokeEditCommand(older,originalEvent.id,5,25,4,-8,.2);assert(oldEdit);auto oldDocument=Document::fromSnapshot(older);assert(oldDocument&&oldDocument.value().apply(oldEdit.value(),older.revision));auto oldEdited=oldDocument.value().snapshot();for(std::size_t i=0;i<later->size();i++)if(i!=1)assert((*oldEdited.eventIndex)[i]==(*older.eventIndex)[i]);assert((*oldEdited.eventIndex)[1].geometry==after.eventIndex->back().geometry);assert(oldDocument.value().undo()&&oldDocument.value().snapshot().sameContent(older));assert(oldDocument.value().redo()&&oldDocument.value().snapshot().sameContent(oldEdited));assert(store.save(path,oldEdited));auto oldReopened=store.recover(path);assert(oldReopened&&oldReopened.value().snapshot.sameContent(oldEdited));std::filesystem::remove(path);
 auto barrier=older;auto barrierEvents=std::make_shared<EventList>(*older.eventIndex);barrier.eventIndex=barrierEvents;auto fill=originalEvent;fill.id=Id::fromNumber(500);fill.engineVersion=8;fill.toolId="bucket";fill.style=StrokeStyle{};fill.startUs=fill.endUs=100000;fill.geometry={{100,100,1,{},{},100000,0,0},{101,100,1,{},{},100000,0,0}};barrierEvents->push_back(fill);assert(!independentNativeStroke(barrier,fill));assert(!editableStrokeIndex(barrier,originalEvent.id)&&!localStrokeEditCommand(barrier,originalEvent.id,5,25,4,-8,.2));auto blocked=Document::fromSnapshot(barrier);assert(blocked&&!blocked.value().apply(oldEdit.value(),barrier.revision)&&blocked.value().snapshot().sameContent(barrier));
 barrierEvents->back().engineVersion=2;barrierEvents->back().toolId="unknown-tool";assert(!independentNativeStroke(barrier,barrierEvents->back())&&!editableStrokeIndex(barrier,originalEvent.id));blocked=Document::fromSnapshot(barrier);assert(blocked&&!blocked.value().apply(oldEdit.value(),barrier.revision));barrierEvents->back().engineVersion=99;assert(!editableStrokeIndex(barrier,originalEvent.id));assert(!editableStrokeIndex(older,originalEvent.id,stop.get_token()));
 std::cout<<"PASS bounded local smooth-stroke edit: arc-length weights/density invariance/coincident samples, exact outside and metadata, Undo/reopen, command bypass/lock/bounds/cancel rejected\n";
